def _sem_acento(t):
    return "".join(c for c in unicodedata.normalize("NFD", t) if unicodedata.category(c) != "Mn")


def _chave(t):
    t = _sem_acento(str(t)).lower().strip()
    t = re.sub(r"[\s\-]+", "_", t)
    return re.sub(r"[^a-z0-9_]", "", t)


def _acha(tipo, nome, validos, alias):
    k = _chave(nome)
    k = alias.get(k, k)
    if k in validos:
        return k
    todos = list(validos) + list(alias)
    sug = difflib.get_close_matches(k, todos, n=1, cutoff=0.6)
    dica = f" Você quis dizer '{alias.get(sug[0], sug[0])}'?" if sug else ""
    raise ValueError(f"{tipo} '{nome}' não existe.{dica} Use palco.ajuda() para ver todos os nomes.")


def _explica(exc):
    """Explica em português os erros mais comuns de quem está aprendendo."""
    m, t = str(exc), type(exc).__name__
    if isinstance(exc, ValueError):
        r = re.search(r"invalid literal for int\(\) with base 10: (.*)$", m)
        if r:
            return f"Você digitou {r.group(1)}, mas aqui o programa precisa de um NÚMERO inteiro (int)."
        r = re.search(r"could not convert string to float: (.*)$", m)
        if r:
            if "," in r.group(1):
                return f"Você digitou {r.group(1)} com VÍRGULA. No Python o número usa PONTO: 7.5"
            return f"Você digitou {r.group(1)}, mas aqui o programa precisa de um NÚMERO (float)."
        if "não existe" in m or "Não achei" in m or "palco" in m or "não está no palco" in m:
            return m
    if isinstance(exc, NameError):
        n = getattr(exc, "name", None) or (re.findall(r"'(.+?)'", m) or ["?"])[0]
        return f"O Python não conhece '{n}'. Escreveu errado ou esqueceu de criar a variável antes?"
    if isinstance(exc, TypeError):
        if "can only concatenate str" in m:
            return "Você juntou TEXTO com NÚMERO usando +. Use f-string: f\"... {variavel} ...\""
        if "unsupported operand" in m and "'str'" in m:
            return "Você fez conta com TEXTO. Faltou o int() ou o float() no input?"
        if "not supported between instances" in m and "'str'" in m:
            return "Você comparou TEXTO com NÚMERO. Faltou o int() no input?"
        if "can't multiply sequence" in m:
            return "Você multiplicou TEXTO por número quebrado. Faltou o int() ou o float() no input?"
        if "missing" in m and "required positional argument" in m:
            return "Faltou colocar alguma coisa dentro dos parênteses do comando."
        if "positional argument" in m and "given" in m:
            return "Um comando recebeu coisas demais dentro dos parênteses."
        if "not callable" in m:
            return "Você usou ( ) depois de algo que não é comando. Será que uma variável ficou com o nome de um comando?"
    if isinstance(exc, ZeroDivisionError):
        return "Dividiu por ZERO! Isso não existe na matemática. Algum número virou 0."
    if isinstance(exc, AttributeError):
        r = re.search(r"module 'palco' has no attribute '(\w+)'", m)
        if r:
            return f"O palco não tem o comando palco.{r.group(1)}. Use palco.ajuda() para ver os comandos."
        r = re.search(r"'(\w+)' object has no attribute '(\w+)'", m)
        if r:
            return f"Não existe .{r.group(2)} para {r.group(1)}. Confira o nome depois do ponto."
    if isinstance(exc, IndexError):
        return "Você pediu uma posição que não existe na lista."
    if isinstance(exc, KeyError):
        return f"A chave {m} não existe no dicionário."
    if isinstance(exc, RecursionError):
        return "Um comando chamou ele mesmo vezes demais."
    return f"{t}: {m}"


# ====================================================================== som (só no Windows, começa desligado)
_TAXA = 16000


def _nota(m):
    return 440.0 * 2 ** ((m - 69) / 12.0)


def _tom(f1, dur, forma="q", vol=0.5, f2=None, ataque=0.005, solta=0.05):
    n = int(_TAXA * dur); out = []; fase = 0.0
    a, s = max(1, ataque * _TAXA), max(1, solta * _TAXA)
    for i in range(n):
        f = f1 if f2 is None else f1 + (f2 - f1) * i / n
        fase += f / _TAXA
        p = fase % 1.0
        v = (1.0 if p < 0.5 else -1.0) if forma == "q" else (4 * abs(p - 0.5) - 1) if forma == "t" else math.sin(2 * math.pi * p)
        out.append(v * vol * min(1.0, i / a, (n - i) / s))
    return out


def _ruido(dur, vol=0.5, cai=True, suave=1.0):
    r = _Random(5); n = int(_TAXA * dur); out = []; ult = 0.0
    for i in range(n):
        ult += (r.uniform(-1, 1) - ult) / suave
        env = (1 - i / n) ** 2 if cai else min(1.0, i / (n * 0.4)) * (1 - i / n)
        out.append(ult * vol * env)
    return out


def _soma(a, b):
    if len(a) < len(b):
        a, b = b, a
    return [x + (b[i] if i < len(b) else 0.0) for i, x in enumerate(a)]


def _junta(*partes):
    out = []
    for p in partes:
        out += p
    return out


_SFX = {
    "golpe": lambda: _soma(_ruido(0.12, 0.7, suave=2), _tom(160, 0.12, "q", 0.4, f2=60)),
    "fogo": lambda: _ruido(0.4, 0.7, suave=6),
    "gelo": lambda: _junta(*[_tom(f, 0.05, "t", 0.4) for f in (1568, 2093, 2637, 3136)]),
    "raio": lambda: _soma(_ruido(0.3, 0.9), _tom(90, 0.3, "q", 0.3, f2=40)),
    "agua": lambda: _junta(*[_tom(300 + k * 60, 0.07, "s", 0.6, f2=700 + k * 60) for k in range(4)]),
    "magia": lambda: _tom(400, 0.3, "q", 0.3, f2=1200),
    "moeda": lambda: _tom(988, 0.07, "q", 0.35) + _tom(1319, 0.3, "q", 0.35, solta=0.25),
    "levelup": lambda: _junta(*[_tom(_nota(m), 0.08, "q", 0.3) for m in (72, 76, 79, 84)]) + _tom(_nota(88), 0.3, "q", 0.3, solta=0.2),
    "pulo": lambda: _tom(300, 0.15, "q", 0.3, f2=900),
    "item": lambda: _junta(*[_tom(f, 0.07, "t", 0.5) for f in (880, 1175, 1760)]),
    "cura": lambda: _tom(400, 0.45, "t", 0.5, f2=900, solta=0.2),
    "explosao": lambda: _ruido(0.7, 0.9, suave=4),
    "erro": lambda: _tom(150, 0.15, "q", 0.35) + _tom(110, 0.3, "q", 0.35),
    "clique": lambda: _tom(1200, 0.03, "q", 0.3),
    "cortina": lambda: _ruido(0.45, 1.6, cai=False, suave=8),
    "festa": lambda: _junta(*[_tom(_nota(m), d, "q", 0.3, solta=0.03) for m, d in ((67, .1), (72, .1), (76, .1), (79, .18), (76, .1), (79, .4))]),
    "emocao": lambda: _tom(1047, 0.06, "t", 0.4) + _tom(1568, 0.09, "t", 0.4),
}
# músicas originais: (batidas por minuto, melodia [(nota, tempos)], baixo [nota a cada 2 tempos]); nota 0 = pausa
_MUS = {
    "aventura": (150, [(72, 1), (76, 1), (79, 1), (76, 1), (77, 1), (81, 1), (79, 2), (76, 1), (74, 1), (72, 1), (74, 1), (76, 2), (74, 2),
                       (72, 1), (76, 1), (79, 1), (84, 1), (83, 1), (81, 1), (79, 2), (77, 1), (76, 1), (74, 1), (71, 1), (72, 4)],
                 [48, 55, 53, 55, 48, 55, 53, 55, 48, 55, 53, 55, 53, 55, 48, 48]),
    "batalha": (176, [(69, .5), (69, .5), (72, .5), (69, .5), (76, 1), (74, .5), (72, .5), (71, .5), (69, .5), (71, .5), (72, .5), (74, 1), (76, 1),
                      (69, .5), (69, .5), (72, .5), (69, .5), (77, 1), (76, .5), (74, .5), (72, .5), (71, .5), (69, .5), (68, .5), (69, 2)],
                [45, 45, 52, 52, 45, 45, 52, 52, 41, 41, 43, 43]),
    "misterio": (92, [(64, 1), (67, 1), (70, 1), (69, 1), (64, 1), (67, 1), (71, 1), (70, 1), (0, 1), (63, 1), (66, 1), (69, 2), (67, 1), (64, 2)],
                 [40, 40, 39, 39, 40, 40, 39, 40]),
    "vitoria": (132, [(67, .5), (72, .5), (76, .5), (79, 1.5), (77, .5), (76, .5), (77, .5), (81, 1.5), (79, .5), (77, .5), (76, .5), (74, .5),
                      (76, .5), (72, 2.5)],
                [48, 53, 55, 48, 48, 48]),
}


def _musica(nome):
    bpm, mel, baixo = _MUS[nome]
    b = 60.0 / bpm
    lead = []
    for m, d in mel:
        lead += _tom(_nota(m), d * b, "q", 0.22, solta=0.04) if m else [0.0] * int(_TAXA * d * b)
    bas = []
    for m in baixo:
        bas += _tom(_nota(m), 2 * b, "t", 0.32, solta=0.08)
    while len(bas) < len(lead):
        bas += bas[: len(lead) - len(bas)]
    return _soma(lead, bas[: len(lead)])


class _Som:
    def __init__(self, palco):
        self.p, self.ligado, self.tocando, self.pasta, self.ok, self.cache, self.volta, self.avisou = palco, False, None, None, None, {}, None, False

    def _pode(self):
        if self.ok is None:
            try:
                import winsound
                self.ws, self.ok = winsound, True
            except ImportError:
                self.ok = False
        if not self.ok and not self.avisou:
            self.avisou = True
            _print("(palco) O som só funciona no Windows.")
        return self.ok

    def _arquivo(self, nome):
        if nome not in self.cache:
            import tempfile, wave
            if not self.pasta:
                self.pasta = tempfile.mkdtemp(prefix="palco_som_")
            amostras = _musica(nome[2:]) if nome.startswith("m_") else _SFX[nome]()
            cam = os.path.join(self.pasta, nome + ".wav")
            with wave.open(cam, "wb") as w:
                w.setnchannels(1); w.setsampwidth(1); w.setframerate(_TAXA)
                w.writeframes(bytes(max(0, min(255, int(128 + 118 * s))) for s in amostras))
            self.cache[nome] = (cam, len(amostras) / _TAXA)
        return self.cache[nome]

    def efeito(self, nome):
        if not self.ligado or not self._pode():
            return
        try:
            cam, dur = self._arquivo(nome)
            self.ws.PlaySound(cam, self.ws.SND_FILENAME | self.ws.SND_ASYNC | self.ws.SND_NODEFAULT)
            if self.tocando:
                if self.volta:
                    self.p.root.after_cancel(self.volta)
                self.volta = self.p.root.after(int(dur * 1000) + 80, self._retoma)
        except Exception:
            pass

    def _retoma(self):
        self.volta = None
        if self.tocando:
            self.musica(self.tocando)

    def musica(self, nome):
        if not self._pode():
            return
        try:
            if not nome:
                self.tocando = None
                self.ws.PlaySound(None, 0)
                return
            self.tocando = nome
            cam, _ = self._arquivo("m_" + nome)
            self.ws.PlaySound(cam, self.ws.SND_FILENAME | self.ws.SND_ASYNC | self.ws.SND_LOOP | self.ws.SND_NODEFAULT)
        except Exception:
            pass


class _Palco:
    def __init__(self):
        self.turbo = max(0.2, float(os.environ.get("PALCO_TURBO", "1")))
        self.vel = self.turbo
        self.fechado = self.acabou = self.comecou = self.deu_erro = self.no_loop = self.cheia = False
        self.codigo_main = None
        self.root = tk.Tk()
        self.root.title("Palco do Python  ·  Ctrl+Play")
        self.root.configure(bg="#000000")
        self.root.resizable(False, False)
        self.root.protocol("WM_DELETE_WINDOW", self._fechar)
        self.cv = tk.Canvas(self.root, width=_W, height=_H, highlightthickness=0, bg="#1e1b4b")
        self.cv.pack(expand=True)
        self.root.bind("<F11>", lambda e: self.tela_cheia())
        self.root.bind("<Escape>", lambda e: self.tela_cheia(False))
        self.fotos, self.minis, self.fundos = {}, {}, {}
        self.fundo = self.cv.create_image(0, 0, anchor="nw")
        self.it, self.nome, self.placa = {}, {}, {}
        self.qual, self.st, self.arma_nome, self.hp, self.bob, self.visivel = {}, {}, {}, {}, {}, {}
        self.balao = {"heroi": [], "npc": [], "narra": []}
        self.cen = None
        self.nomeheroi = "VOCÊ"
        self.bolsa = {}
        self.clima, self.gotas, self.t_clima = None, [], 0.0
        self.noite, self.veu = False, None
        self.plac = self.plac_fundo = None
        self.entrada = tk.Entry(self.root, font=("Courier New", 18, "bold"), width=22, bg="#fffbeb", fg="#1e1b4b",
                                relief="flat", highlightthickness=3, highlightcolor="#facc15", highlightbackground="#facc15")
        self.entrada.bind("<Return>", self._enter)
        self.resposta = None
        self.som = _Som(self)
        for s in ("heroi", "npc"):
            self._cria_slot(s)
        self.cenario("floresta"); self.npc("ogro"); self.heroi("menino")
        self._monta_cortina()
        self.atualiza()

    def _cria_slot(self, s):
        x = _SLOT[s]
        self.it[s] = self.cv.create_image(x, _CHAO, anchor="s", tags=("lado_" + s, "corpo_" + s))
        self.placa[s] = self.cv.create_rectangle(0, 0, 0, 0, fill="#1e1b4b", outline="", tags=("lado_" + s, "placas"))
        self.nome[s] = self.cv.create_text(x, _CHAO + 22, font=("Arial", 13 if s in ("heroi", "npc") else 11, "bold"), fill="white",
                                           tags=("lado_" + s, "placas"))
        self.qual[s], self.st[s], self.arma_nome[s], self.hp[s], self.bob[s], self.visivel[s] = None, None, None, None, 0, True

    # ================================================================ cortina e título
    def _monta_cortina(self):
        for lado, x1, x2 in (("cortE", -10, 460), ("cortD", 440, 910)):
            tags = ("cortina", lado)
            self.cv.create_rectangle(x1, 0, x2, _H, fill="#b91c1c", outline="", tags=tags)
            for x in range(x1 + 18, x2, 38):
                self.cv.create_line(x, 0, x, _H, fill="#7f1d1d", width=12, tags=tags)
                self.cv.create_line(x + 14, 0, x + 14, _H, fill="#dc2626", width=4, tags=tags)
            borda = x2 - 6 if lado == "cortE" else x1 + 6
            self.cv.create_line(borda, 0, borda, _H, fill="#facc15", width=8, tags=tags)
            self.cv.create_line(x1, _H - 8, x2, _H - 8, fill="#facc15", width=6, dash=(6, 4), tags=tags)
        self.cv.create_polygon(0, 0, 0, 0, smooth=True, fill="#450a0a", outline="#facc15", width=5, tags=("cortina", "cortTxt", "cortPlaca"))
        for dx, cor in ((3, "#000000"), (0, "#facc15")):
            self.cv.create_text(_W // 2 + dx, _H // 2 - 10 + dx, text="PALCO DO PYTHON", font=("Arial", 34, "bold"), fill=cor, width=800,
                                justify="center", tags=("cortina", "cortTxt", "cortTit"))
        self.cv.create_text(_W // 2, _H // 2 + 56, text="", font=("Arial", 19, "bold"), fill="white", width=760, justify="center",
                            tags=("cortina", "cortTxt", "cortSub"))
        self._placa_titulo()

    def _placa_titulo(self):
        self.cv.itemconfig("cortTxt", state="normal")
        b = self.cv.bbox("cortTit")
        if self.cv.itemcget(self.cv.find_withtag("cortSub")[0], "text").strip():
            b2 = self.cv.bbox("cortSub")
            b = (min(b[0], b2[0]), b[1], max(b[2], b2[2]), b2[3])
        self.cv.coords("cortPlaca", *self._forma(b[0] - 34, b[1] - 22, b[2] + 34, b[3] + 22, 22))

    def _cortina(self, fechar, titulo=None, sub=""):
        passos = 16
        d = 480 / passos
        self.cv.tag_raise("cortina")
        if not fechar:
            self.cv.itemconfig("cortTxt", state="hidden")
        self.som.efeito("cortina")
        for _ in range(passos):
            if self.fechado:
                return
            self.cv.move("cortE", d if fechar else -d, 0)
            self.cv.move("cortD", -d if fechar else d, 0)
            self.atualiza(); time.sleep(0.03 / self.vel)
        if fechar and titulo:
            self.cv.itemconfig("cortTit", text=titulo); self.cv.itemconfig("cortSub", text=sub)
            self._placa_titulo()
            self.cv.itemconfig("cortTxt", state="normal")
            self.cv.tag_raise("cortTxt")
            self.atualiza()

    def _comeca(self):
        if self.comecou or self.fechado:
            return
        self.comecou = True
        self.espera(0.5)
        self._cortina(False)

    def titulo(self, texto, sub=""):
        texto, sub = str(texto), str(sub)
        _print(f"[Título] {texto}" + (f"  ·  {sub}" if sub else ""))
        if self.fechado:
            return
        if not self.comecou:
            self.cv.itemconfig("cortTit", text=texto); self.cv.itemconfig("cortSub", text=sub)
            self._placa_titulo()
            self.cv.itemconfig("cortTxt", state="normal"); self.cv.tag_raise("cortina")
            self.som.efeito("cortina")
            self.atualiza()
            self.espera(2.8)
        else:
            for q in ("npc", "heroi", "narra"):
                self._limpa(q)
            self._cortina(True, texto, sub)
            self.espera(2.5)
            self._cortina(False)

    def creditos(self, *linhas):
        linhas = [str(l) for l in linhas] or ["Obrigado por jogar!"]
        for l in linhas:
            _print(f"[Créditos] {l}")
        if self.fechado:
            return
        self._comeca()
        for q in ("npc", "heroi", "narra"):
            self._limpa(q)
        self.cv.create_rectangle(0, 0, _W, _H, fill="#0b0820", outline="", tags="creditos")
        for _ in range(70):
            x, y = _rnd.randint(0, _W), _rnd.randint(0, _H)
            self.cv.create_rectangle(x, y, x + 2, y + 2, fill=_rnd.choice(("#ffffff", "#fde047", "#a5b4fc")), outline="", tags="creditos")
        y = _H + 40
        self.cv.create_text(_W / 2, y, text="FIM", font=("Arial", 56, "bold"), fill="#facc15", tags=("creditos", "credtxt"))
        y += 92
        for l in linhas:
            self.cv.create_text(_W / 2, y, text=l, font=("Arial", 22, "bold"), fill="white", width=760, justify="center", tags=("creditos", "credtxt"))
            y += 54
        self.cv.create_text(_W / 2, y + 6, text="feito com o Palco do Python · Ctrl+Play", font=("Arial", 13), fill="#a78bfa", tags=("creditos", "credtxt"))
        altura = (y + 6) - (_H + 40)
        dist = (_H + 40) - (_H - altura) / 2 if altura <= _H - 60 else (y + 6) - (_H - 30)
        self.cv.tag_raise("cortina")
        self.som.efeito("festa")
        quadros = max(10, int(dist / 3))
        self._rodar(quadros, lambda f: self.cv.move("credtxt", 0, -dist / quadros), dt=0.03)
        self.espera(1.0)

    def tela_cheia(self, ligar=None):
        if self.fechado:
            return
        self.cheia = (not self.cheia) if ligar is None else bool(ligar)
        try:
            self.root.resizable(True, True)
            self.root.attributes("-fullscreen", self.cheia)
            if not self.cheia:
                self.root.resizable(False, False)
        except tk.TclError:
            pass
        self.atualiza()

    # ================================================================ imagens
    def _mini(self, chave):
        if chave not in self.minis:
            self.minis[chave] = tk.PhotoImage(data=_IMG[chave])
        return self.minis[chave]

    def _foto(self, chave, zoom, modo=None, espelho=False):
        k = (chave, zoom, modo, espelho)
        if k not in self.fotos:
            base = self._mini(chave)
            if modo or espelho:
                base = self._pinta(base, modo, espelho)
            self.fotos[k] = base.zoom(zoom) if zoom > 1 else base
        return self.fotos[k]

    def _pinta(self, mini, modo, espelho):
        w, h = mini.width(), mini.height()
        out = tk.PhotoImage(width=w, height=h)
        tinta = _TINTA.get(modo)
        for y in range(h):
            for x in range(w):
                try:
                    if mini.transparency_get(x, y):
                        continue
                except (AttributeError, tk.TclError):
                    pass
                c = mini.get(x, y)
                if isinstance(c, str):
                    c = tuple(int(v) for v in c.split())
                r, g, b = c[:3]
                if tinta == "x":
                    if (x + y) % 2:
                        continue
                    r, g, b = (r + 255) // 2, (g + 255) // 2, (b + 255) // 2
                elif modo == "petrificado":
                    m = int(0.3 * r + 0.59 * g + 0.11 * b)
                    r = g = b = 60 + m * 3 // 5
                elif tinta:
                    tr, tg, tb, a = tinta
                    r, g, b = int(r + (tr - r) * a), int(g + (tg - g) * a), int(b + (tb - b) * a)
                out.put("#%02x%02x%02x" % (r, g, b), (w - 1 - x if espelho else x, y))
        return out

    def _imagem(self, s):
        nome = self.qual[s]
        lado = "d" if _LADO[s] == "heroi" else "e"
        st = self.st[s]
        return self._foto(f"p:{nome}:{lado}", _PERS[nome]["z"], st if st in _TINTA else None)

    def _arquivo(self, nome):
        nome = str(nome)
        bases = []
        f = getattr(sys.modules.get("__main__"), "__file__", None)
        if f:
            bases.append(os.path.dirname(os.path.abspath(f)))
        bases.append(os.getcwd())
        for b in bases:
            c = os.path.join(b, nome)
            if os.path.isfile(c):
                return c
        if os.path.isfile(nome):
            return nome
        raise ValueError(f"Não achei o arquivo '{nome}'. Ele tem que estar na MESMA pasta do seu programa, com o nome igualzinho (com .png).")

    def _carrega_pers(self, nome):
        caminho = self._arquivo(nome)
        base = os.path.splitext(os.path.basename(caminho))[0]
        k = "arq_" + _chave(base)
        if k not in _PERS:
            img = tk.PhotoImage(file=caminho)
            w, h = img.width(), img.height()
            if h > 200:
                img = img.subsample(math.ceil(h / 180))
                w, h = img.width(), img.height()
            self.minis[f"p:{k}:d"] = img
            self.minis[f"p:{k}:e"] = self._pinta(img, None, True)
            _PERS[k] = {"tela": base.upper()[:18], "cor": "#7c3aed", "z": max(1, round(140 / h)) if h < 120 else 1, "voa": 0}
        return k

    def _carrega_fundo(self, nome):
        caminho = self._arquivo(nome)
        base = os.path.splitext(os.path.basename(caminho))[0]
        k = "arq_" + _chave(base)
        if k not in self.fundos:
            img = tk.PhotoImage(file=caminho)
            w, h = img.width(), img.height()
            if w < _W or h < _H:
                z = math.ceil(max(_W / w, _H / h))
                img = img.zoom(z) if z > 1 else img
            elif w >= 2 * _W and h >= 2 * _H:
                img = img.subsample(int(min(w / _W, h / _H)))
            self.fundos[k] = img
            _CEN[k] = base.upper()[:24]
        return k

    def _acha_pers(self, nome):
        if str(nome).lower().endswith((".png", ".gif")):
            return self._carrega_pers(nome)
        return _acha("personagem", nome, _PERS, _AL_PERS)

    def _slot(self, quem, padrao=None):
        if quem is None:
            return padrao
        k = _chave(quem)
        if k in _AL_QUEM:
            return _AL_QUEM[k]
        if k in ("aliado", "aliada", "amigo", "amiga", "companheiro", "companheira") and self.qual.get("aliado"):
            return "aliado"
        if k in ("npc2", "npc3") and self.qual.get(k):
            return k
        nome = _AL_PERS.get(k, k)
        for s in ("heroi", "npc", "aliado", "npc2", "npc3"):
            if self.qual.get(s) in (nome, "arq_" + _chave(os.path.splitext(str(quem))[0])):
                return s
        raise ValueError(f"'{quem}' não está no palco agora. Use \"heroi\", \"npc\" ou o nome de um personagem que está em cena.")

    def _caixa(self, s):
        b = self.cv.bbox(self.it[s]) if s in self.it else None
        return b if b else (_SLOT[s] - 50, _CHAO - 130, _SLOT[s] + 50, _CHAO)

    def _centro(self, s):
        x1, y1, x2, y2 = self._caixa(s)
        return (x1 + x2) / 2, (y1 + y2) / 2

    def _mao(self, s):
        x1, y1, x2, y2 = self._caixa(s)
        return (x2 - 12 if _LADO[s] == "heroi" else x1 + 12), y1 + (y2 - y1) * 0.42

    # ================================================================ montar a cena
    def cenario(self, nome):
        nome = self._carrega_fundo(nome) if str(nome).lower().endswith((".png", ".gif")) else _acha("cenário", nome, _CEN, _AL_CEN)
        if self.fechado or nome == self.cen:
            return
        no_meio = self.comecou
        if no_meio:
            for q in ("npc", "heroi", "narra"):
                self._limpa(q)
            self._cortina(True, _CEN[nome])
        self.cen = nome
        self._fundo()
        if no_meio:
            self.espera(0.7)
            self._cortina(False)
        self.atualiza()

    def _fundo(self):
        n = self.cen
        if self.veu:
            self.cv.delete(self.veu); self.veu = None
        if n in self.fundos:
            self.cv.itemconfig(self.fundo, image=self.fundos[n], anchor="center"); self.cv.coords(self.fundo, _W / 2, _H / 2)
            if self.noite:
                try:
                    self.veu = self.cv.create_rectangle(0, 0, _W, _H, fill="#0b1030", outline="", stipple="gray50")
                    self.cv.tag_raise(self.veu, self.fundo)
                except tk.TclError:
                    self.veu = None
        else:
            self.cv.itemconfig(self.fundo, image=self._foto(("n:" if self.noite else "c:") + n, 4), anchor="nw"); self.cv.coords(self.fundo, 0, 0)

    def _limpa_lado(self, s, barra=True):
        self.cv.delete("st_" + s)
        self.cv.delete("arma_" + s)
        self.st[s] = None
        self.arma_nome[s] = None
        if barra:
            self.cv.delete("barra_" + s)
            self.hp[s] = None
        self.visivel[s] = True
        self.cv.itemconfig("corpo_" + s, state="normal")

    def _poe(self, s, nome):
        self.qual[s] = nome
        c = self.cv.coords(self.it[s])
        self.cv.coords(self.it[s], c[0] if c else _SLOT[s], _CHAO - _PERS[nome]["voa"])
        self.bob[s] = 0
        self.cv.itemconfig(self.it[s], image=self._imagem(s))
        self._placas()

    def _anda(self, s, dx, passos=20):
        for i in range(passos):
            if self.fechado:
                return
            self.cv.move("lado_" + s, dx / passos, -5 if i % 2 else 5)
            self.atualiza(); time.sleep(0.025 / self.vel)

    def npc(self, nome):
        nome = self._acha_pers(nome)
        if self.fechado or nome == self.qual["npc"]:
            return
        no_meio = self.comecou
        if no_meio:
            self._limpa("npc"); self._limpa("narra")
            self._anda("npc", 330)
        self._limpa_lado("npc")
        self._poe("npc", nome)
        if no_meio:
            self._anda("npc", -330)
        self.atualiza()

    def heroi(self, nome):
        nome = self._acha_pers(nome)
        if self.fechado or nome == self.qual["heroi"]:
            return
        self._limpa_lado("heroi", barra=False)
        if self.comecou:
            self._fumaca("heroi")
        self._poe("heroi", nome)
        if self.hp["heroi"]:
            self._barra("heroi", *self.hp["heroi"], animar=False)
        if self.comecou:
            for dy in (-8, -8, -6, -4, 4, 6, 8, 8):
                self.cv.move("corpo_heroi", 0, dy); self.atualiza(); time.sleep(0.03 / self.vel)
        self.atualiza()

    def entra(self, nome, lado="npc"):
        nome = self._acha_pers(nome)
        meu = _chave(lado) in ("heroi", "voce", "eu", "aliado", "aliada", "amigo", "amiga")
        if self.fechado:
            return
        livres = [s for s in (("aliado",) if meu else ("npc2", "npc3")) if not self.qual.get(s)]
        if not livres:
            raise ValueError("O palco já está cheio desse lado (no máximo 2 do seu lado e 3 do lado do programa). Use palco.sai(...) antes.")
        s = livres[0]
        if s not in self.it:
            self._cria_slot(s)
        self._limpa_lado(s)
        dx = -320 if meu else 330
        self.qual[s] = nome
        self.cv.coords(self.it[s], _SLOT[s] + dx, _CHAO - _PERS[nome]["voa"])
        self.cv.coords(self.nome[s], _SLOT[s] + dx, _CHAO + 22)
        self.cv.itemconfig(self.it[s], image=self._imagem(s))
        if s in ("aliado", "npc2"):
            self.cv.tag_lower("corpo_" + s, self.it["heroi" if s == "aliado" else "npc"])
        self._placas()
        if self.comecou:
            self.som.efeito("pulo")
            self._anda(s, -dx)
        else:
            self.cv.move("lado_" + s, -dx, 0)
        self._placas()
        self._por_cima()
        self.atualiza()

    def sai(self, quem):
        s = self._slot(quem)
        if s in ("heroi", "npc"):
            raise ValueError("O herói e o personagem principal não saem de cena: troque com palco.heroi(...) ou palco.npc(...).")
        if self.fechado:
            return
        if self.comecou:
            self._limpa(_LADO[s])
            self._anda(s, -320 if _LADO[s] == "heroi" else 330)
        self.cv.delete("lado_" + s)
        for d in (self.it, self.nome, self.placa):
            d.pop(s, None)
        self.qual[s] = None
        self._placas()
        self.atualiza()

    def nome_heroi(self, texto):
        self.nomeheroi = str(texto).upper()[:18] or "VOCÊ"
        self._placa("heroi")
        self.atualiza()

    def _placas(self):
        for s in list(self.it):
            if self.qual.get(s):
                self._placa(s)

    def _placa(self, s):
        nome = self.qual[s]
        if s == "heroi":
            texto, cor = self.nomeheroi, "#b45309"
        else:
            texto, cor = _PERS[nome]["tela"], _PERS[nome]["cor"]
            if s == "npc" and not (self.qual.get("npc2") or self.qual.get("npc3")):
                texto += " · o programa"
        self.cv.itemconfig(self.nome[s], text=texto)
        x1, y1, x2, y2 = self.cv.bbox(self.nome[s])
        self.cv.coords(self.placa[s], x1 - 10, y1 - 4, x2 + 10, y2 + 4)
        self.cv.itemconfig(self.placa[s], fill=cor)

    # ================================================================ balões e conversa
    def _limpa(self, lado):
        for i in self.balao[lado]:
            self.cv.delete(i)
        self.balao[lado] = []

    def _forma(self, x1, y1, x2, y2, r=18):
        return [x1 + r, y1, x2 - r, y1, x2, y1, x2, y1 + r, x2, y2 - r, x2, y2, x2 - r, y2, x1 + r, y2, x1, y2, x1, y2 - r, x1, y1 + r, x1, y1]

    def fala(self, s, texto, cor_borda=None, pergunta=False):
        if self.fechado:
            return
        self._comeca()
        lado = _LADO[s]
        self._limpa(lado)
        self._limpa("narra")
        largura = 360
        x0 = 470 if lado == "npc" else 40
        alvo = self._caixa(s)
        tmp = self.cv.create_text(x0 + 22, 40, text=texto, font=("Arial", 17, "bold"), width=largura, anchor="nw")
        bx1, by1, bx2, by2 = self.cv.bbox(tmp)
        self.cv.delete(tmp)
        topo = alvo[1]
        y2 = min(topo - 40, 330)
        y1 = y2 - (by2 - by1) - 30
        if y1 < 62:
            y1 = 62; y2 = y1 + (by2 - by1) + 30
        x1, x2 = x0, x0 + max(150, (bx2 - bx1) + 44)
        if lado == "npc":
            x2 = 880; x1 = max(440, x2 - max(150, (bx2 - bx1) + 44))
        cx = min(max((alvo[0] + alvo[2]) / 2, x1 + 30), x2 - 30)
        borda = cor_borda or ("#facc15" if s == "heroi" else _PERS[self.qual[s]]["cor"])
        fundo = "#fffbeb" if lado == "heroi" else "white"
        bico_x = (alvo[0] + alvo[2]) / 2
        bico = max(y2 + 4, topo - 8)
        rabo = self.cv.create_polygon(cx - 18, y2 - 2, cx + 14, y2 - 2, bico_x - 4, bico, fill=fundo, outline=borda, width=3)
        caixa = self.cv.create_polygon(self._forma(x1, y1, x2, y2), smooth=True, fill=fundo, outline=borda, width=3)
        cobre = self.cv.create_line(cx - 16, y2 - 2, cx + 12, y2 - 2, fill=fundo, width=4)
        txt = self.cv.create_text(x1 + 22, y1 + 15, text="", font=("Arial", 17, "bold"), width=largura, anchor="nw", fill="#1e1b4b")
        self.balao[lado] = [rabo, caixa, cobre, txt]
        self._por_cima()
        alto = 0
        for i in range(1, len(texto) + 1):
            if self.fechado:
                return
            self.cv.itemconfig(txt, text=texto[:i])
            novo = -6 if (i // 4) % 2 else 0
            if novo != alto:
                self.cv.move("corpo_" + s, 0, novo - alto); alto = novo
            self.atualiza(); time.sleep(0.028 / self.vel)
        if alto:
            self.cv.move("corpo_" + s, 0, -alto)
        self.atualiza()

    def diz(self, texto, quem="heroi"):
        s = self._slot(quem)
        texto = str(texto)
        _print(f"{self.nomeheroi if s == 'heroi' else _PERS[self.qual[s]]['tela']}: {texto}")
        if self.fechado or not texto.strip():
            return
        self.fala(s, texto)
        self.espera(0.9 + min(2.2, len(texto) * 0.03))

    def _larg(self, texto, fonte):
        t = self.cv.create_text(0, 0, text=texto, font=fonte, anchor="nw")
        b = self.cv.bbox(t); self.cv.delete(t)
        return b[2] - b[0]

    def _escolhe(self, o):
        self.resposta = o

    def escolha(self, *opcoes, pergunta=None):
        if len(opcoes) == 1 and isinstance(opcoes[0], (list, tuple)):
            opcoes = tuple(opcoes[0])
        ops = [str(o) for o in opcoes]
        if not 2 <= len(ops) <= 6:
            raise ValueError("palco.escolha precisa de 2 a 6 opções, por exemplo: palco.escolha(\"Atacar\", \"Fugir\")")
        if self.fechado:
            return _input(" / ".join(ops) + ": ")
        if pergunta:
            _print(pergunta)
            self.fala("npc", str(pergunta))
        self._comeca()
        self._limpa("heroi")
        self.resposta = None
        fonte = ("Arial", 16, "bold")
        larg = max(230, min(400, max(self._larg(o, fonte) for o in ops) + 80))
        y0 = 72 if self.plac is None else 80
        alt, gap = 46, 9
        t = self.cv.create_text(44, y0, text="ESCOLHA (clique ou aperte o número):", anchor="w", font=("Arial", 12, "bold"), fill="#1e1b4b", tags="botoes")
        f = self.cv.create_rectangle(self.cv.bbox(t), fill="#facc15", outline="#facc15", width=4, tags="botoes")
        self.cv.tag_raise(t, f)
        caixas = []
        for i, o in enumerate(ops):
            y = y0 + 18 + i * (alt + gap)
            tag = f"bot{i}"
            r = self.cv.create_polygon(self._forma(40, y, 40 + larg, y + alt, 14), smooth=True, fill="#fffbeb", outline="#facc15", width=3, tags=("botoes", tag))
            self.cv.create_oval(52, y + 9, 80, y + 37, fill="#7c3aed", outline="", tags=("botoes", tag))
            self.cv.create_text(66, y + 23, text=str(i + 1), font=("Arial", 13, "bold"), fill="white", tags=("botoes", tag))
            self.cv.create_text(92, y + 23, text=o, anchor="w", font=fonte, fill="#1e1b4b", width=larg - 60, tags=("botoes", tag))
            self.cv.tag_bind(tag, "<Button-1>", lambda e, o=o: self._escolhe(o))
            self.cv.tag_bind(tag, "<Enter>", lambda e, r=r: (self.cv.itemconfig(r, fill="#fde68a"), self.cv.config(cursor="hand2")))
            self.cv.tag_bind(tag, "<Leave>", lambda e, r=r: (self.cv.itemconfig(r, fill="#fffbeb"), self.cv.config(cursor="")))
            caixas.append(r)

        def tecla(e):
            if e.char and e.char.isdigit() and 1 <= int(e.char) <= len(ops):
                self._escolhe(ops[int(e.char) - 1])
        self.root.bind("<Key>", tecla)
        self.cv.focus_set()
        self._por_cima()
        auto = os.environ.get("PALCO_RESPOSTAS")
        if auto is not None:
            fila = auto.split("|")
            ja = int(os.environ.get("_PALCO_I", "0"))
            alvo = fila[ja] if ja < len(fila) else ""
            os.environ["_PALCO_I"] = str(ja + 1)
            i = int(alvo) - 1 if alvo.isdigit() and 1 <= int(alvo) <= len(ops) else next((k for k, o in enumerate(ops) if _chave(o) == _chave(alvo)), 0)
            self.espera(0.9)
            self.cv.itemconfig(caixas[i], fill="#fde68a"); self.espera(0.4)
            self.resposta = ops[i]
        while self.resposta is None and not self.fechado:
            self.atualiza(); time.sleep(0.02)
        if self.fechado:
            raise SystemExit
        self.root.unbind("<Key>")
        self.cv.config(cursor="")
        self.cv.delete("botoes")
        self.som.efeito("clique")
        _print(f"> {self.resposta}")
        self.fala("heroi", self.resposta)
        self.espera(0.5)
        return self.resposta

    def emocao(self, nome, quem="npc"):
        bruto = str(nome).strip()
        k = _AL_EMO.get(bruto) or _acha("emoção", bruto, _EMOCOES, _AL_EMO)
        s = self._slot(quem)
        if self.fechado:
            return
        self._comeca()
        x1, y1, x2, y2 = self._caixa(s)
        cx, cy = (x1 + x2) / 2, max(52, y1 - 52)
        tg = "emocao"
        self.cv.create_polygon(self._forma(cx - 30, cy - 24, cx + 30, cy + 22, 12), smooth=True, fill="white", outline="#1e1b4b", width=3, tags=tg)
        self.cv.create_polygon(cx - 7, cy + 20, cx + 7, cy + 20, cx, cy + 32, fill="white", outline="#1e1b4b", width=3, tags=tg)
        self.cv.create_line(cx - 6, cy + 20, cx + 6, cy + 20, fill="white", width=4, tags=tg)
        txt = {"surpresa": ("!", "#dc2626"), "duvida": ("?", "#2563eb"), "amor": ("♥", "#ec4899"), "feliz": ("♪", "#ca8a04"),
               "silencio": ("...", "#1e1b4b"), "sono": ("Z z", "#6366f1")}
        if k in txt:
            self.cv.create_text(cx, cy, text=txt[k][0], font=("Arial", 36 if k != "sono" else 25, "bold"), fill=txt[k][1], tags=("emocao", "emotxt"))
        elif k == "raiva":
            for dx, dy in ((-1, -1), (1, -1), (-1, 1), (1, 1)):
                self.cv.create_line(cx + dx * 4, cy + dy * 13, cx + dx * 4, cy + dy * 4, cx + dx * 13, cy + dy * 4, fill="#dc2626", width=4, tags=tg)
        elif k in ("nervoso", "triste"):
            for dx in ((0,) if k == "nervoso" else (-9, 9)):
                self.cv.create_oval(cx + dx - 7, cy - 2, cx + dx + 7, cy + 12, fill="#60a5fa", outline="", tags=tg)
                self.cv.create_polygon(cx + dx - 6, cy + 2, cx + dx + 6, cy + 2, cx + dx, cy - 13, fill="#60a5fa", outline="", tags=tg)
        elif k == "ideia":
            self.cv.create_oval(cx - 10, cy - 16, cx + 10, cy + 4, fill="#fde047", outline="#ca8a04", width=2, tags=tg)
            self.cv.create_rectangle(cx - 5, cy + 4, cx + 5, cy + 11, fill="#9ca3af", outline="", tags=tg)
            for a in (-60, -30, 0, 30, 60):
                r = math.radians(a - 90)
                self.cv.create_line(cx + math.cos(r) * 14, cy - 6 + math.sin(r) * 14, cx + math.cos(r) * 20, cy - 6 + math.sin(r) * 20,
                                    fill="#ca8a04", width=2, tags=tg)
        for i in self.cv.find_withtag(tg):
            if "emotxt" not in self.cv.gettags(i):
                self.cv.scale(i, cx, cy, 1.4, 1.4)
        self.cv.move(tg, 0, 10)
        self.som.efeito("emocao")
        self._rodar(6, lambda f: self.cv.move(tg, 0, -2 if f < 5 else 0))
        self.espera(1.3)
        self.cv.delete(tg)
        self.atualiza()

    def narrar(self, texto):
        texto = str(texto)
        _print(f"[Narrador] {texto}")
        if self.fechado:
            return
        self._comeca()
        for q in ("npc", "heroi", "narra"):
            self._limpa(q)
        fonte = ("Arial", 22, "bold")
        tmp = self.cv.create_text(_W // 2, 116, text=texto, font=fonte, width=700, justify="center")
        x1, y1, x2, y2 = self.cv.bbox(tmp)
        self.cv.delete(tmp)
        caixa = self.cv.create_rectangle(x1 - 30, y1 - 16, x2 + 30, y2 + 16, fill="#fef3c7", outline="#92400e", width=5)
        friso = self.cv.create_rectangle(x1 - 22, y1 - 8, x2 + 22, y2 + 8, outline="#d97706", width=2)
        txt = self.cv.create_text(_W // 2, (y1 + y2) // 2, text="", font=fonte, width=700, justify="center", fill="#451a03")
        self.balao["narra"] = [caixa, friso, txt]
        self._por_cima()
        for i in range(1, len(texto) + 1):
            if self.fechado:
                return
            self.cv.itemconfig(txt, text=texto[:i]); self.atualiza(); time.sleep(0.035 / self.vel)
        self.espera(1.1 + min(2.0, len(texto) * 0.03))

    def placar(self, texto):
        texto = str(texto)
        if self.fechado:
            return
        if self.plac is None:
            self.plac_fundo = self.cv.create_rectangle(0, 0, 0, 0, fill="#1e1b4b", outline="#facc15", width=3)
            self.plac = self.cv.create_text(28, 26, anchor="w", font=("Arial", 15, "bold"), fill="white")
        self.cv.itemconfig(self.plac, text=texto)
        if texto.strip():
            x1, y1, x2, y2 = self.cv.bbox(self.plac)
            self.cv.coords(self.plac_fundo, x1 - 14, y1 - 7, x2 + 14, y2 + 7)
            self.cv.itemconfig(self.plac_fundo, state="normal"); self.cv.itemconfig(self.plac, state="normal")
        else:
            self.cv.itemconfig(self.plac_fundo, state="hidden"); self.cv.itemconfig(self.plac, state="hidden")
        self._por_cima()
        if self.comecou and texto.strip():
            for _ in range(2):
                self.cv.itemconfig(self.plac_fundo, fill="#facc15"); self.cv.itemconfig(self.plac, fill="#1e1b4b")
                self.atualiza(); time.sleep(0.12 / self.vel)
                self.cv.itemconfig(self.plac_fundo, fill="#1e1b4b"); self.cv.itemconfig(self.plac, fill="white")
                self.atualiza(); time.sleep(0.12 / self.vel)
        self.atualiza()

    def _por_cima(self):
        for t in ("placas", "barras", "statusx"):
            self.cv.tag_raise(t)
        for lista in self.balao.values():
            for i in lista:
                self.cv.tag_raise(i)
        if self.plac is not None:
            self.cv.tag_raise(self.plac_fundo); self.cv.tag_raise(self.plac)
        for t in ("bolsa", "botoes", "emocao", "creditos", "cortina"):
            self.cv.tag_raise(t)

    # ================================================================ partículas
    def _q(self, x, y, s, cor, tags=()):
        return self.cv.create_rectangle(x - s / 2, y - s / 2, x + s / 2, y + s / 2, fill=cor, outline="", tags=tags)

    def _rodar(self, quadros, passo, dt=0.022):
        for f in range(quadros):
            if self.fechado:
                return
            passo(f)
            self.atualiza(); time.sleep(dt / self.vel)

    def _explode(self, x, y, cores, n=26, forca=8.0, s=9, quadros=20, g=0.45, sobe=2.0):
        ps = []
        for i in range(n):
            a = _rnd.uniform(0, 2 * math.pi); v = _rnd.uniform(forca * 0.3, forca)
            ps.append([self._q(x, y, _rnd.choice((s, s - 3, s + 2)), cores[i % len(cores)]), v * math.cos(a), v * math.sin(a) - sobe])

        def passo(f):
            for p in ps:
                self.cv.move(p[0], p[1], p[2]); p[2] += g; p[1] *= 0.96
            if f > quadros * 0.6:
                for p in ps[:: 3]:
                    self.cv.itemconfig(p[0], state="hidden")
        self._rodar(quadros, passo)
        for p in ps:
            self.cv.delete(p[0])

    def _sobe(self, s, cores, n=16, quadros=28, forma="q", tam=8, texto=None):
        x1, y1, x2, y2 = self._caixa(s)
        ps = []
        for i in range(n):
            x, y = _rnd.uniform(x1, x2), _rnd.uniform(y1 + (y2 - y1) * 0.3, y2)
            cor = cores[i % len(cores)]
            if forma == "mais":
                it = [self.cv.create_rectangle(x - tam / 2, y - 1.5 * tam, x + tam / 2, y + 1.5 * tam, fill=cor, outline=""),
                      self.cv.create_rectangle(x - 1.5 * tam, y - tam / 2, x + 1.5 * tam, y + tam / 2, fill=cor, outline="")]
            elif forma == "bolha":
                it = [self.cv.create_oval(x - tam, y - tam, x + tam, y + tam, outline=cor, width=3)]
            elif forma == "texto":
                it = [self.cv.create_text(x, y, text=texto, font=("Arial", 16 + i % 3 * 4, "bold"), fill=cor)]
            else:
                it = [self._q(x, y, tam, cor)]
            ps.append([it, _rnd.uniform(-0.8, 0.8), _rnd.uniform(-4.5, -2.0), _rnd.randint(0, quadros // 2)])

        def passo(f):
            for p in ps:
                if f >= p[3]:
                    for i in p[0]:
                        self.cv.move(i, p[1], p[2])
                if f > quadros * 0.75 and _rnd.random() < 0.3:
                    for i in p[0]:
                        self.cv.itemconfig(i, state="hidden")
        self._rodar(quadros, passo)
        for p in ps:
            for i in p[0]:
                self.cv.delete(i)

    def _apanha(self, s):
        self.som.efeito("golpe")
        for k in range(6):
            self.cv.itemconfig("corpo_" + s, state="hidden" if k % 2 == 0 else "normal")
            self.cv.move("corpo_" + s, 8 if k % 2 == 0 else -8, 0)
            self.atualiza(); time.sleep(0.05 / self.vel)
        if not self.visivel[s]:
            self.cv.itemconfig("corpo_" + s, state="hidden")

    def _flash(self, cor="white", vezes=2):
        for _ in range(vezes):
            r = self.cv.create_rectangle(0, 0, _W, _H, fill=cor, outline="")
            self.cv.tag_raise("cortina")
            self.atualiza(); time.sleep(0.05 / self.vel)
            self.cv.delete(r); self.atualiza(); time.sleep(0.06 / self.vel)

    def _fumaca(self, s):
        cx, cy = self._centro(s)
        bs = []
        for i in range(14):
            a = i / 14 * 2 * math.pi
            bs.append([self.cv.create_oval(cx - 10, cy - 10, cx + 10, cy + 10, fill=("#e5e7eb", "#cbd5e1", "#94a3b8")[i % 3], outline=""),
                       math.cos(a) * 5, math.sin(a) * 4])

        def passo(f):
            for b in bs:
                self.cv.move(b[0], b[1], b[2] - 0.6)
                x1, y1, x2, y2 = self.cv.coords(b[0])
                self.cv.coords(b[0], x1 - 1.2, y1 - 1.2, x2 + 1.2, y2 + 1.2)
            if f > 14:
                for b in bs[f % 3:: 3]:
                    self.cv.itemconfig(b[0], state="hidden")
        self._rodar(20, passo)
        for b in bs:
            self.cv.delete(b[0])

    # ================================================================ poderes, ataque e pulo
    def _projetil(self, a, b, cores, s=10, n=22, arco=-50, rastro=True, flecha=False):
        (x1, y1), (x2, y2) = a, b
        offs = [(0, 0)] if flecha else [(0, 0), (-s, 0), (s, 0), (0, -s), (0, s), (-s / 2, -s / 2), (s / 2, s / 2)]
        corpo = [self._q(x1, y1, s, cores[i % len(cores)]) for i in range(len(offs))]
        haste = self.cv.create_line(x1, y1, x1, y1, fill=cores[0], width=5, arrow="last", arrowshape=(16, 20, 8)) if flecha else None
        trilha = []

        def passo(f):
            t = (f + 1) / n
            x = x1 + (x2 - x1) * t
            y = y1 + (y2 - y1) * t + arco * 4 * t * (1 - t)
            for it, (dx, dy) in zip(corpo, offs):
                self.cv.coords(it, x + dx - s / 2, y + dy - s / 2, x + dx + s / 2, y + dy + s / 2)
            if haste:
                dx = (x2 - x1) / n * 4
                self.cv.coords(haste, x - dx * 3, y, x, y)
            if rastro:
                for _ in range(2):
                    trilha.append([self._q(x + _rnd.uniform(-s, s), y + _rnd.uniform(-s, s), s * 0.7, _rnd.choice(cores)), 7])
            for p in trilha:
                p[1] -= 1
                if p[1] <= 0:
                    self.cv.itemconfig(p[0], state="hidden")
        self._rodar(n, passo)
        for it in corpo + [p[0] for p in trilha]:
            self.cv.delete(it)
        if haste:
            self.cv.delete(haste)

    def _zigue(self, x, y_fim, larg=40, partes=7):
        pts, y = [x + _rnd.uniform(-larg, larg), -10], -10
        passo = (y_fim + 10) / partes
        for k in range(partes):
            y += passo
            pts += [x + (_rnd.uniform(-larg, larg) if k < partes - 1 else 0), y]
        return pts

    def _oponente(self, s):
        return "npc" if _LADO[s] == "heroi" else "heroi"

    def poder(self, nome, de="heroi", em=None):
        nome = _acha("poder", nome, _PODERES, _AL_POD)
        de = self._slot(de)
        alvo = self._slot(em) if em else self._oponente(de)
        if self.fechado:
            return
        self._comeca()
        for q in ("heroi", "npc", "narra"):
            self._limpa(q)
        self.som.efeito({"fogo": "fogo", "meteoro": "fogo", "sol_de_apolo": "fogo", "gelo": "gelo", "raio": "raio", "raio_de_zeus": "raio",
                         "agua": "agua", "onda_de_poseidon": "agua", "cura": "cura"}.get(nome, "magia"))
        a, b = self._mao(de), self._centro(alvo)
        FOGO = ["#fde047", "#f97316", "#ef4444", "#fb923c", "#facc15"]
        if nome == "fogo":
            self._projetil(a, b, FOGO, s=10, arco=-60)
            self._explode(*b, FOGO, n=30); self._apanha(alvo)
        elif nome == "gelo":
            self._projetil(a, b, ["#e0f2fe", "#7dd3fc", "#38bdf8", "#ffffff"], s=9, arco=-30)
            self._explode(*b, ["#e0f2fe", "#7dd3fc", "#ffffff", "#0ea5e9"], n=26, g=0.2); self._apanha(alvo)
        elif nome == "agua":
            self._projetil(a, b, ["#60a5fa", "#3b82f6", "#bfdbfe", "#1d4ed8"], s=10, arco=-90)
            self._explode(*b, ["#60a5fa", "#93c5fd", "#ffffff"], n=30, g=0.8, sobe=4); self._apanha(alvo)
        elif nome == "sombra":
            self._projetil(a, b, ["#7c3aed", "#4c1d95", "#1e1b4b", "#a78bfa"], s=11, arco=-20)
            self._explode(*b, ["#7c3aed", "#1e1b4b", "#a78bfa"], n=26, g=0.1); self._apanha(alvo)
        elif nome == "veneno":
            self._projetil(a, b, ["#84cc16", "#4d7c0f", "#bef264"], s=9, arco=-70)
            self._explode(*b, ["#84cc16", "#bef264", "#4d7c0f"], n=18, g=0.3); self._apanha(alvo)
            self._sobe(alvo, ["#84cc16", "#bef264"], n=12, forma="bolha", tam=7)
        elif nome == "flecha_de_artemis":
            self._projetil(a, b, ["#e2e8f0", "#ffffff", "#cbd5e1"], s=6, n=12, arco=-8, flecha=True)
            self._explode(*b, ["#ffffff", "#e2e8f0", "#c7d2fe"], n=20, forca=6, s=6); self._apanha(alvo)
        elif nome == "luz":
            raio = self.cv.create_line(a[0], a[1], b[0], b[1], fill="#fde047", width=2, capstyle="round")
            miolo = self.cv.create_line(a[0], a[1], b[0], b[1], fill="#ffffff", width=1, capstyle="round")
            self._rodar(10, lambda f: (self.cv.itemconfig(raio, width=4 + f * 2.4), self.cv.itemconfig(miolo, width=1 + f)))
            self._explode(*b, ["#fef9c3", "#fde047", "#ffffff"], n=24, g=0.05)
            self._rodar(8, lambda f: (self.cv.itemconfig(raio, width=max(1, 28 - f * 3.5)), self.cv.itemconfig(miolo, width=max(1, 11 - f * 1.4))))
            self.cv.delete(raio); self.cv.delete(miolo); self._apanha(alvo)
        elif nome in ("raio", "raio_de_zeus"):
            vezes, larg = (3, 70) if nome == "raio_de_zeus" else (2, 40)
            for k in range(vezes):
                xs = [b[0]] if nome == "raio" else [b[0] - 40, b[0], b[0] + 40]
                linhas = []
                for x in xs:
                    pts = self._zigue(x, b[1], larg if x == b[0] else 25)
                    linhas += [self.cv.create_line(*pts, fill="#fde047", width=9 if nome == "raio_de_zeus" else 7),
                               self.cv.create_line(*pts, fill="#ffffff", width=3)]
                self._flash("#fefce8" if k % 2 == 0 else "white", 1)
                self.atualiza(); time.sleep(0.09 / self.vel)
                for l in linhas:
                    self.cv.delete(l)
            self._explode(*b, ["#fde047", "#ffffff", "#facc15"], n=40 if nome == "raio_de_zeus" else 26, forca=9)
            if nome == "raio_de_zeus":
                self.tremer()
            self._apanha(alvo)
        elif nome == "tornado":
            x0, y0 = b[0], self._caixa(alvo)[3]
            its = []

            def passo(f):
                for i in its:
                    self.cv.delete(i)
                its.clear()
                for k in range(10):
                    w = 14 + k * 9
                    cx = x0 + math.sin(f * 0.5 + k * 0.6) * 16
                    y = y0 - k * 22
                    its.append(self.cv.create_oval(cx - w, y - 8, cx + w, y + 8, outline=("#e5e7eb", "#94a3b8", "#ffffff")[(k + f) % 3], width=4))
                self.cv.move("corpo_" + alvo, 6 if f % 2 else -6, 0)
            self._rodar(34, passo)
            for i in its:
                self.cv.delete(i)
            self._apanha(alvo)
        elif nome == "pedras":
            x1, y1, x2, y2 = self._caixa(alvo)
            for k in range(5):
                x = _rnd.uniform(x1, x2)
                p = [self._q(x, -20, 22, "#78716c"), self._q(x - 3, -23, 10, "#a8a29e")]
                fim_y = y1 + _rnd.uniform(10, (y2 - y1) * 0.5)
                self._rodar(10, lambda f, p=p, fy=fim_y: [self.cv.move(i, 0, (fy + 20) / 10) for i in p])
                for i in p:
                    self.cv.delete(i)
                self._explode(x, fim_y, ["#a8a29e", "#78716c", "#d6d3d1"], n=12, forca=5, s=7, quadros=10)
            self._apanha(alvo)
        elif nome == "meteoro":
            ini = (b[0] - 420 if _LADO[de] == "heroi" else b[0] + 420, -60)
            self._projetil(ini, b, ["#78350f", "#f97316", "#facc15", "#ef4444"], s=16, n=26, arco=0)
            self.som.efeito("explosao")
            self._explode(*b, FOGO + ["#78716c"], n=50, forca=11, s=12, quadros=26)
            self.tremer(); self._apanha(alvo)
        elif nome == "onda_de_poseidon":
            dirx = 1 if _LADO[de] == "heroi" else -1
            base = _CHAO + 30
            ond = []

            def passo(f):
                for i in ond:
                    self.cv.delete(i)
                ond.clear()
                frente = -150 + f * 34 if dirx == 1 else _W + 150 - f * 34
                pts = []
                for k in range(0, 31):
                    x = frente - dirx * k * 32
                    alt = 230 * math.exp(-((k - 3) ** 2) / 40.0) + 40
                    pts += [x, base - alt + math.sin(k * 0.9 + f) * 8]
                pts += [frente - dirx * 1000, base, frente + dirx * 20, base]
                ond.append(self.cv.create_polygon(*pts, fill="#0ea5e9", outline="#0369a1", width=3, smooth=True))
                ond.append(self.cv.create_line(*pts[: 18], fill="#ffffff", width=6, smooth=True))
                if abs(frente - self._centro(alvo)[0]) < 40:
                    self.cv.move("corpo_" + alvo, dirx * 10, -6)
            self._rodar(36, passo, dt=0.03)
            for i in ond:
                self.cv.delete(i)
            self._recoloca(alvo)
            self._apanha(alvo)
        elif nome == "sol_de_apolo":
            sx, sy = b[0], 90
            sol = self.cv.create_oval(sx, sy, sx, sy, fill="#fde047", outline="#f59e0b", width=4)
            raios = []

            def nasce(f):
                r = 8 + f * 3
                self.cv.coords(sol, sx - r, sy - r, sx + r, sy + r)
                for l in raios:
                    self.cv.delete(l)
                raios.clear()
                for k in range(12):
                    an = k / 12 * 2 * math.pi + f * 0.15
                    raios.append(self.cv.create_line(sx + math.cos(an) * (r + 6), sy + math.sin(an) * (r + 6),
                                                     sx + math.cos(an) * (r + 26), sy + math.sin(an) * (r + 26), fill="#facc15", width=5))
            self._rodar(14, nasce)
            feixes = [self.cv.create_line(sx + d, sy + 40, b[0] + d * 0.6, b[1], fill="#fef08a", width=8) for d in (-30, 0, 30)]
            self._flash("#fef9c3", 2)
            self._explode(*b, ["#fde047", "#ffffff", "#facc15"], n=30)
            for i in feixes + raios + [sol]:
                self.cv.delete(i)
            self._apanha(alvo)
        elif nome == "cura":
            self._sobe(de, ["#22c55e", "#86efac", "#16a34a"], n=14, forma="mais", tam=5)
        elif nome == "escudo":
            x1, y1, x2, y2 = self._caixa(de)
            cx, cy = (x1 + x2) / 2, (y1 + y2) / 2
            bo = self.cv.create_oval(cx, cy, cx, cy, outline="#67e8f9", width=5)
            self._rodar(12, lambda f: self.cv.coords(bo, cx - (x2 - x1) * 0.06 * (f + 1), cy - (y2 - y1) * 0.06 * (f + 1),
                                                     cx + (x2 - x1) * 0.06 * (f + 1), cy + (y2 - y1) * 0.06 * (f + 1)))
            self.cv.delete(bo)
            self.status("protegido", de)
        self._por_cima()
        self.atualiza()

    def _recoloca(self, s):
        c = self.cv.coords(self.it[s])
        self.cv.coords(self.it[s], self.cv.coords(self.nome[s])[0], _CHAO - _PERS[self.qual[s]]["voa"])
        self.bob[s] = 0
        self._redesenha(s)

    def ataque(self, de="heroi", em=None):
        a = self._slot(de)
        alvo = self._slot(em) if em else self._oponente(a)
        if self.fechado:
            return
        self._comeca()
        for q in ("heroi", "npc", "narra"):
            self._limpa(q)
        ca, cb = self._caixa(a), self._caixa(alvo)
        sinal = 1 if (cb[0] + cb[2]) > (ca[0] + ca[2]) else -1
        dist = max(0, (cb[0] - ca[2] + 16) if sinal > 0 else (ca[0] - cb[2] + 16))
        tag, passos = "corpo_" + a, 10
        self._rodar(passos, lambda f: self.cv.move(tag, sinal * dist / passos, -6 if f % 2 else 6), dt=0.018)
        x = cb[0] if sinal > 0 else cb[2]
        self._explode(x, (cb[1] + cb[3]) / 2, ["#ffffff", "#fde047", "#f97316"], n=18, forca=6, s=7, quadros=10, g=0.1)
        self._apanha(alvo)
        self._rodar(passos, lambda f: self.cv.move(tag, -sinal * dist / passos, 0), dt=0.022)
        self.atualiza()

    def pular(self, quem="heroi"):
        s = self._slot(quem)
        if self.fechado:
            return
        self._comeca()
        self.som.efeito("pulo")
        for dy in (-14, -12, -10, -7, -4, -1, 1, 4, 7, 10, 12, 14):
            self.cv.move("corpo_" + s, 0, dy); self.atualiza(); time.sleep(0.025 / self.vel)

    # ================================================================ armas e itens
    def arma(self, nome, quem="heroi"):
        s = self._slot(quem)
        if self.fechado:
            return
        self.cv.delete("arma_" + s)
        k = _chave(nome)
        if k in ("", "nada", "nenhuma", "sem_arma", "tirar"):
            self.arma_nome[s] = None
            self.atualiza()
            return
        k = _acha("arma ou item", nome, _OBJ, _AL_OBJ)
        self.arma_nome[s] = k
        self._desenha_arma(s)
        if self.comecou:
            x, y = self._mao(s)
            self.som.efeito("item")
            self._explode(x, y, ["#fde047", "#ffffff"], n=12, forca=4, s=5, quadros=10, g=0.1)
        self._por_cima()
        self.atualiza()

    def _desenha_arma(self, s):
        self.cv.delete("arma_" + s)
        k = self.arma_nome[s]
        if not k:
            return
        x, y = self._mao(s)
        foto = self._foto("i:" + k, 4, None, espelho=(_LADO[s] == "npc"))
        self.cv.create_image(x, y, image=foto, tags=("lado_" + s, "corpo_" + s, "arma_" + s))
        if not self.visivel[s] or self.st[s] == "invisivel":
            self.cv.itemconfig("arma_" + s, state="hidden")

    def item(self, nome):
        k = _acha("item", nome, _OBJ, _AL_OBJ)
        if self.fechado:
            return
        self._comeca()
        x1, y1, x2, y2 = self._caixa("heroi")
        cx = (x1 + x2) / 2
        ic = self.cv.create_image(cx, y1 - 10, image=self._foto("i:" + k, 4))
        sombra = self.cv.create_text(cx + 2, y1 - 58, text="+ " + _OBJ[k], font=("Arial", 15, "bold"), fill="#1e1b4b")
        tx = self.cv.create_text(cx, y1 - 60, text="+ " + _OBJ[k], font=("Arial", 15, "bold"), fill="#fde047")
        self.som.efeito("item")
        self._rodar(14, lambda f: (self.cv.move(ic, 0, -3 if f < 7 else 1), self.cv.move(tx, 0, -1), self.cv.move(sombra, 0, -1)))
        self._explode(cx, y1 - 20, ["#fde047", "#ffffff", "#facc15"], n=14, forca=5, s=6, quadros=12, g=0.1)
        self.cv.delete(tx); self.cv.delete(sombra)
        sx, sy = self.cv.coords(ic)
        self._rodar(14, lambda f: self.cv.move(ic, (860 - sx) / 14, (30 - sy) / 14))
        self.cv.delete(ic)
        self.bolsa[k] = self.bolsa.get(k, 0) + 1
        self._desenha_bolsa()
        self.atualiza()

    def usar(self, nome):
        k = _acha("item", nome, _OBJ, _AL_OBJ)
        if self.fechado:
            return
        if not self.bolsa.get(k):
            _print(f"(palco) A bolsa não tem {_OBJ[k]}.")
            return
        self._comeca()
        self.bolsa[k] -= 1
        if not self.bolsa[k]:
            del self.bolsa[k]
        self._desenha_bolsa()
        x, y = self._centro("heroi")
        ic = self.cv.create_image(860, 30, image=self._foto("i:" + k, 4))
        self._rodar(14, lambda f: self.cv.move(ic, (x - 860) / 14, (y - 30) / 14))
        self.cv.delete(ic)
        self.som.efeito("cura" if k.startswith("pocao") else "item")
        cores = {"pocao": ["#22c55e", "#86efac"], "pocao_mana": ["#3b82f6", "#93c5fd"], "pocao_veneno": ["#84cc16", "#4d7c0f"]}.get(k, ["#fde047", "#ffffff"])
        self._sobe("heroi", cores, n=12, forma="mais" if k.startswith("pocao") else "q", tam=5)
        self.atualiza()

    def tem(self, nome):
        k = _acha("item", nome, _OBJ, _AL_OBJ)
        return self.bolsa.get(k, 0)

    def _desenha_bolsa(self):
        self.cv.delete("bolsa")
        if not self.bolsa:
            return
        n = len(self.bolsa)
        x2 = 890; x1 = x2 - 38 * n - 82
        self.cv.create_rectangle(x1, 8, x2, 52, fill="#1e1b4b", outline="#facc15", width=3, tags="bolsa")
        self.cv.create_text(x1 + 12, 30, text="BOLSA", anchor="w", font=("Arial", 11, "bold"), fill="#fde047", tags="bolsa")
        for i, (k, qtd) in enumerate(self.bolsa.items()):
            x = x1 + 82 + i * 38 + 16
            self.cv.create_image(x, 30, image=self._foto("i:" + k, 2), tags="bolsa")
            if qtd > 1:
                self.cv.create_text(x + 14, 44, text=f"x{qtd}", font=("Arial", 9, "bold"), fill="white", tags="bolsa")
        self._por_cima()

    # ================================================================ status, vida, dano
    def status(self, nome, quem="npc"):
        k = _acha("status", nome, _STATUS, _AL_ST)
        s = self._slot(quem)
        if self.fechado:
            return
        self._comeca()
        self.cv.delete("st_" + s)
        self.st[s] = None if k == "normal" else k
        self.cv.itemconfig(self.it[s], image=self._imagem(s))
        if k == "normal":
            if self.visivel[s]:
                self.cv.itemconfig("arma_" + s, state="normal")
            self._sobe(s, ["#fde047", "#ffffff"], n=10, tam=6, quadros=18)
            self.atualiza()
            return
        anima = {"queimando": (["#f97316", "#facc15", "#ef4444"], "q", None), "envenenado": (["#84cc16", "#bef264"], "bolha", None),
                 "congelado": (["#e0f2fe", "#7dd3fc", "#ffffff"], "q", None), "paralisado": (["#fde047", "#facc15"], "q", None),
                 "petrificado": (["#a8a29e", "#d6d3d1"], "q", None), "dormindo": (["#c7d2fe", "#a5b4fc"], "texto", "Z"),
                 "confuso": (["#fde047", "#f9a8d4"], "texto", "?"), "forte": (["#ef4444", "#fca5a5"], "q", None),
                 "invisivel": (["#ffffff", "#e2e8f0"], "q", None), "protegido": (["#67e8f9", "#a5f3fc"], "bolha", None)}[k]
        self.som.efeito({"queimando": "fogo", "congelado": "gelo", "paralisado": "raio"}.get(k, "magia"))
        self._sobe(s, anima[0], n=14, forma=anima[1], texto=anima[2], tam=7)
        self._marca_status(s)
        if k == "invisivel":
            self.cv.itemconfig("arma_" + s, state="hidden")
        self._por_cima()
        self.atualiza()

    def _marca_status(self, s):
        self.cv.delete("st_" + s)
        k = self.st[s]
        if not k:
            return
        texto, cor = _STATUS[k]
        x1, y1, x2, y2 = self._caixa(s)
        tags = ("lado_" + s, "st_" + s, "statusx")
        px = self.cv.coords(self.nome[s])[0]
        t = self.cv.create_text(px, _CHAO + 68, text=texto, font=("Arial", 10, "bold"), fill="white", tags=tags)
        bx1, by1, bx2, by2 = self.cv.bbox(t)
        f = self.cv.create_rectangle(bx1 - 8, by1 - 3, bx2 + 8, by2 + 3, fill=cor, outline="white", width=2, tags=tags)
        self.cv.tag_raise(t, f)
        ct = ("lado_" + s, "corpo_" + s, "st_" + s)
        fora = -1 if _LADO[s] == "heroi" else 1
        lado_x = x1 - 4 if fora < 0 else x2 + 4
        if k == "dormindo":
            for i, tam in enumerate((12, 16, 20)):
                self.cv.create_text(lado_x + fora * i * 14, y1 + 4 - i * 16, text="Z", font=("Arial", tam, "bold"), fill="#c7d2fe", tags=ct)
        elif k == "confuso":
            self.cv.create_text((x1 + x2) / 2, y1 - 22, text="? ? ?", font=("Arial", 18, "bold"), fill="#fde047", tags=ct)
        elif k == "protegido":
            self.cv.create_oval(x1 - 16, y1 - 14, x2 + 16, y2 + 8, outline="#67e8f9", width=4, tags=ct)
        elif k == "paralisado":
            for dx in (-1, 1):
                cx = (x1 + x2) / 2 + dx * (x2 - x1) * 0.55
                self.cv.create_line(cx, y1 + 10, cx + 10, y1 + 26, cx - 4, y1 + 30, cx + 8, y1 + 48, fill="#fde047", width=4, tags=ct)

    def _redesenha(self, s):
        self._desenha_arma(s)
        self._marca_status(s)
        if self.hp[s]:
            self._barra(s, *self.hp[s], animar=False)

    def _barra(self, s, v, mx, animar=True, antes=None):
        self.cv.delete("barra_" + s)
        cx = self.cv.coords(self.nome[s])[0]
        w, y = 120, _CHAO + 44
        tags = ("lado_" + s, "barra_" + s, "barras")
        self.cv.create_rectangle(cx - w / 2 - 3, y - 9, cx + w / 2 + 3, y + 9, fill="#0f172a", outline="white", width=2, tags=tags)
        enche = self.cv.create_rectangle(cx - w / 2, y - 6, cx - w / 2, y + 6, outline="", tags=tags)
        txt = self.cv.create_text(cx, y, text="", font=("Arial", 9, "bold"), fill="white", tags=tags)

        def pinta(valor):
            r = max(0.0, min(1.0, valor / mx)) if mx else 0
            cor = "#22c55e" if r > 0.5 else "#facc15" if r > 0.25 else "#ef4444"
            self.cv.coords(enche, cx - w / 2, y - 6, cx - w / 2 + w * r, y + 6)
            self.cv.itemconfig(enche, fill=cor)
            self.cv.itemconfig(txt, text=f"VIDA {int(round(valor))}/{int(mx)}")
        if animar and antes is not None and antes != v:
            for f in range(1, 11):
                pinta(antes + (v - antes) * f / 10)
                self.atualiza(); time.sleep(0.03 / self.vel)
        pinta(v)
        self.cv.tag_raise(txt)

    def vida(self, quem, valor, maximo=None):
        s = self._slot(quem)
        if self.fechado:
            return
        v = max(0, float(valor))
        antes = self.hp[s][0] if self.hp[s] else None
        mx = float(maximo) if maximo else (self.hp[s][1] if self.hp[s] else max(1.0, v))
        mx = max(mx, v)
        self.hp[s] = (v, mx)
        self._barra(s, v, mx, animar=self.comecou, antes=antes)
        self._por_cima()
        self.atualiza()

    def _numero(self, s, texto, cor):
        if self.fechado:
            return None
        self._comeca()
        x1, y1, x2, y2 = self._caixa(s)
        cx = (x1 + x2) / 2
        return (self.cv.create_text(cx + 3, y1 + 3, text=texto, font=("Arial", 30, "bold"), fill="#1e1b4b"),
                self.cv.create_text(cx, y1, text=texto, font=("Arial", 30, "bold"), fill=cor))

    def dano(self, n, quem="npc"):
        s = self._slot(quem)
        par = self._numero(s, f"-{n}", "#ef4444")
        if not par:
            return
        self._apanha(s)
        self._rodar(16, lambda f: [self.cv.move(i, 0, -3) for i in par])
        self.espera(0.3)
        for i in par:
            self.cv.delete(i)
        self.atualiza()

    def cura(self, n, quem="heroi"):
        s = self._slot(quem)
        par = self._numero(s, f"+{n}", "#22c55e")
        if not par:
            return
        self.som.efeito("cura")
        self._sobe(s, ["#22c55e", "#86efac"], n=8, forma="mais", tam=4, quadros=16)
        self._rodar(14, lambda f: [self.cv.move(i, 0, -3) for i in par])
        self.espera(0.3)
        for i in par:
            self.cv.delete(i)
        self.atualiza()

    # ================================================================ efeitos
    def efeito(self, nome, quem=None):
        nome = _acha("efeito", nome, _EFEITOS, _AL_EF)
        if self.fechado:
            return
        s = self._slot(quem) if quem else ("heroi" if nome in ("level_up", "estrelas") else "npc")
        if nome in ("noite", "dia"):
            self.noite = nome == "noite"
            if self.comecou:
                self._flash("#0f172a" if self.noite else "#fefce8", 1)
            self._fundo(); self.atualiza()
            return
        if nome in ("chuva", "neve", "limpo"):
            self._clima(None if nome == "limpo" else nome)
            return
        self._comeca()
        if nome == "level_up":
            x1, y1, x2, y2 = self._caixa(s)
            cx = (x1 + x2) / 2
            sh = self.cv.create_text(cx + 3, y1 - 17, text="LEVEL UP!", font=("Arial", 32, "bold"), fill="#78350f")
            t = self.cv.create_text(cx, y1 - 20, text="LEVEL UP!", font=("Arial", 32, "bold"), fill="#fde047")
            self.som.efeito("levelup")
            for dy in (-10, -10, -6, 6, 10, 10):
                self.cv.move("corpo_" + s, 0, dy); self.atualiza(); time.sleep(0.03 / self.vel)
            self._sobe(s, ["#fde047", "#ffffff", "#facc15"], n=20, tam=7)
            self._rodar(14, lambda f: (self.cv.move(sh, 0, -2), self.cv.move(t, 0, -2)))
            self.espera(0.5)
            self.cv.delete(sh); self.cv.delete(t)
        elif nome == "moedas":
            self.som.efeito("moeda")
            ms = [[self.cv.create_image(_rnd.randint(30, _W - 30), _rnd.randint(-300, -20), image=self._foto("i:moeda", 2)), 0.0, False] for _ in range(28)]

            def passo(f):
                for m in ms:
                    m[1] += 0.9
                    self.cv.move(m[0], 0, m[1])
                    if self.cv.coords(m[0])[1] > _CHAO and not m[2]:
                        m[1] = -m[1] * 0.5; m[2] = True
            self._rodar(46, passo)
            for m in ms:
                self.cv.delete(m[0])
        elif nome == "explosao":
            cx, cy = self._centro(s)
            self.som.efeito("explosao")
            self._explode(cx, cy, ["#fde047", "#f97316", "#ef4444", "#78716c", "#ffffff"], n=56, forca=12, s=13, quadros=26)
            self.tremer(); self._fumaca(s)
        elif nome == "fumaca":
            self._fumaca(s)
        elif nome == "sumir":
            self._fumaca(s)
            self.visivel[s] = False
            self.cv.itemconfig("corpo_" + s, state="hidden")
        elif nome == "aparecer":
            self._fumaca(s)
            self.visivel[s] = True
            self.cv.itemconfig("corpo_" + s, state="normal")
        elif nome == "relampago":
            x = _rnd.randint(300, 600)
            pts = self._zigue(x, 260, 60)
            ls = [self.cv.create_line(*pts, fill="#fde047", width=7), self.cv.create_line(*pts, fill="white", width=3)]
            self.som.efeito("raio")
            self._flash("white", 2)
            for l in ls:
                self.cv.delete(l)
            self.tremer()
        elif nome == "terremoto":
            self.som.efeito("explosao")
            for _ in range(3):
                self.tremer()
        elif nome == "coracoes":
            self.som.efeito("emocao")
            self._sobe(s, ["#f472b6", "#ec4899", "#fda4af"], n=12, forma="texto", texto="♥", quadros=34)
        elif nome == "estrelas":
            self.som.efeito("item")
            self._sobe(s, ["#fde047", "#ffffff", "#facc15"], n=22, tam=7, quadros=30)
        elif nome == "festa":
            self.festa()
        self._por_cima()
        self.atualiza()

    def _clima(self, tipo):
        for g in self.gotas:
            self.cv.delete(g[0])
        self.gotas = []
        self.clima = tipo
        if not tipo:
            self.atualiza()
            return
        for _ in range(95 if tipo == "chuva" else 75):
            x, y = _rnd.uniform(0, _W), _rnd.uniform(0, _H)
            if tipo == "chuva":
                it = self.cv.create_line(x, y, x - 4, y + 16, fill="#2563eb", width=2)
                self.gotas.append([it, -2.0, 15.0])
            else:
                r = _rnd.choice((2, 3, 4))
                it = self.cv.create_oval(x - r, y - r, x + r, y + r, fill="white", outline="")
                self.gotas.append([it, _rnd.uniform(-0.8, 0.8), _rnd.uniform(1.5, 3.0)])
        self.t_clima = time.time()
        self._por_cima()
        self.atualiza()

    def _passo_fundo(self):
        agora = time.time()
        for s, nome in self.qual.items():
            if nome and _PERS[nome]["voa"] and s in self.it:
                alvo = int(round(5 * math.sin(agora * 2.6 + _SLOT[s] / 200)))
                if alvo != self.bob[s]:
                    self.cv.move("corpo_" + s, 0, alvo - self.bob[s]); self.bob[s] = alvo
        if self.clima and agora - self.t_clima >= 0.03:
            k = min(3.0, (agora - self.t_clima) / 0.03)
            self.t_clima = agora
            for g in self.gotas:
                self.cv.move(g[0], g[1] * k, g[2] * k)
                c = self.cv.coords(g[0])
                if c and c[1] > _H:
                    self.cv.move(g[0], _rnd.uniform(-40, 40), -(_H + 30))

    def som_liga(self, ligar=True):
        self.som.ligado = bool(ligar)
        if ligar:
            self.som._pode()

    def musica(self, nome):
        k = _chave(nome)
        if k in ("", "parar", "pare", "nenhuma", "sem_musica", "silencio", "desligar"):
            self.som.musica(None)
            return
        self.som.musica(_acha("música", nome, _MUSICAS, {"luta": "batalha", "chefe": "batalha", "suspense": "misterio", "medo": "misterio",
                                                         "vitorioso": "vitoria", "final": "vitoria", "viagem": "aventura"}))

    def ajuda(self):
        _print("\n========== PALCO DO PYTHON · TODOS OS NOMES ==========")
        for titulo, lista in _GRUPOS:
            if lista:
                _print(f"\n{titulo}:")
                _print("  " + ", ".join(lista))
            else:
                _print(f"\n{titulo}")
        _print("\nPODERES (palco.poder):\n  " + ", ".join(_PODERES))
        _print("\nSTATUS (palco.status):\n  " + ", ".join(_STATUS))
        _print("\nEFEITOS (palco.efeito):\n  " + ", ".join(_EFEITOS))
        _print("\nEMOÇÕES (palco.emocao):\n  ! ? amor raiva nervoso triste feliz ideia ... sono")
        _print("\nMÚSICAS (palco.musica):\n  " + ", ".join(_MUSICAS) + ", parar")
        _print("\nCOMANDOS NOVOS: palco.diz · palco.escolha · palco.entra · palco.sai · palco.emocao · palco.ataque · palco.pular")
        _print("  palco.titulo · palco.creditos · palco.tela_cheia · palco.som · palco.musica · palco.vida")
        _print("  Seu desenho também vale: palco.heroi(\"meu_heroi.png\") · palco.cenario(\"meu_fundo.png\")")
        _print("======================================================\n")

    # ================================================================ efeitos antigos
    def tremer(self):
        if self.fechado:
            return
        self._comeca()
        for dx, dy in ((14, 4), (-26, -6), (22, 6), (-18, -4), (14, 2), (-10, -2), (4, 0)):
            self.cv.move("all", dx, dy)
            self.atualiza(); time.sleep(0.04 / self.vel)

    def festa(self):
        if self.fechado:
            return
        self._comeca()
        self.som.efeito("festa")
        cores = ("#facc15", "#ec4899", "#22d3ee", "#a3e635", "#f97316", "#a855f7", "#ffffff")
        ps = []
        for _ in range(110):
            x, y = _rnd.randint(0, _W), _rnd.randint(-420, -10)
            w = _rnd.choice((6, 8, 10))
            ps.append((self.cv.create_rectangle(x, y, x + w, y + w + 4, fill=_rnd.choice(cores), outline=""), _rnd.uniform(-2.5, 2.5), _rnd.uniform(7, 13)))
        self._por_cima()
        self._rodar(62, lambda f: [self.cv.move(i, vx, vy) for i, vx, vy in ps], dt=0.025)
        for i, _vx, _vy in ps:
            self.cv.delete(i)
        self.atualiza()

    # ================================================================ perguntas
    def _enter(self, _evento=None):
        self.resposta = self.entrada.get()

    def pergunta(self):
        self._comeca()
        auto = os.environ.get("PALCO_RESPOSTAS")
        self._limpa("heroi")
        self.resposta = None
        self.entrada.delete(0, "end")
        jan = self.cv.create_window(40, 200, window=self.entrada, anchor="w")
        rot = self.cv.create_text(42, 168, text="SUA RESPOSTA (aperte Enter):", font=("Arial", 13, "bold"), fill="#1e1b4b", anchor="w")
        fr = self.cv.create_rectangle(self.cv.bbox(rot), fill="#facc15", outline="#facc15")
        self.cv.tag_raise(rot, fr)
        self.entrada.focus_force()
        if auto is not None:
            fila = auto.split("|")
            ja = int(os.environ.get("_PALCO_I", "0"))
            alvo = fila[ja] if ja < len(fila) else ""
            os.environ["_PALCO_I"] = str(ja + 1)
            self.espera(0.5)
            for ch in alvo:
                self.entrada.insert("end", ch); self.atualiza(); time.sleep(0.09 / self.turbo)
            self.espera(0.4); self.resposta = alvo
        while self.resposta is None and not self.fechado:
            self.atualiza(); time.sleep(0.02)
        if self.fechado:
            raise SystemExit
        self.cv.delete(jan); self.cv.delete(rot); self.cv.delete(fr)
        return self.resposta

    # ================================================================ utilidades
    def espera(self, seg):
        fim = time.time() + float(seg) / self.vel
        while time.time() < fim and not self.fechado:
            self.atualiza(); time.sleep(0.02)

    def atualiza(self):
        if self.fechado:
            return
        try:
            self._passo_fundo()
            self.root.update()
        except tk.TclError:
            self.fechado = True

    def _tique(self):
        if self.fechado:
            return
        try:
            self._passo_fundo()
            self.root.after(30, self._tique)
        except tk.TclError:
            self.fechado = True

    def _fechar(self):
        self.fechado = True
        self.som.tocando = None
        if self.som.ok:
            try:
                self.som.ws.PlaySound(None, 0)
            except Exception:
                pass
        try:
            self.root.destroy()
        except tk.TclError:
            pass

    def _linha_erro(self, exc):
        tb, linha, arquivo = exc.__traceback__, None, None
        meu = self.codigo_main.co_filename if self.codigo_main is not None else None
        while tb is not None:
            if meu and tb.tb_frame.f_code.co_filename == meu:
                linha, arquivo = tb.tb_lineno, meu
            tb = tb.tb_next
        codigo = linecache.getline(arquivo, linha).strip() if linha and arquivo else ""
        return linha, codigo

    def erro(self, exc):
        if self.fechado or self.acabou or isinstance(exc, (SystemExit, KeyboardInterrupt)):
            return
        self.acabou = True
        self.deu_erro = True
        linha, codigo = self._linha_erro(exc)
        expl = _explica(exc)
        onde = f" na linha {linha}" if linha else ""
        _print(f"\n[Palco] ERRO{onde}" + (f":  {codigo}" if codigo else ""))
        _print(f"[Palco] O que aconteceu: {expl}\n")
        self.som.efeito("erro")
        self.cv.delete("botoes")
        self._limpa("heroi")
        self.fala("npc", f"Ops! ERRO{onde}. {expl}", cor_borda="#dc2626")

    def fim(self):
        if self.fechado or self.no_loop:
            return
        if self.acabou and not self.deu_erro:
            return
        self._comeca()
        self.acabou = True
        self.no_loop = True
        if self.deu_erro:
            aviso, cor = "O PROGRAMA PAROU POR CAUSA DE UM ERRO  ·  veja o Shell", "#991b1b"
        else:
            aviso, cor = "FIM DA CENA  ·  pode fechar a janela", "#1e1b4b"
        f = self.cv.create_text(_W // 2, _H - 20, text=aviso, font=("Arial", 15, "bold"), fill="white")
        b = self.cv.create_rectangle(self.cv.bbox(f), fill=cor, outline=cor, width=10)
        self.cv.tag_raise(f, b)
        self._tique()
        try:
            self.root.mainloop()
        except (tk.TclError, KeyboardInterrupt):
            pass


_P = _Palco()


def _novo_print(*args, sep=" ", end="\n", file=None, flush=False):
    if file not in (None, sys.stdout):
        return _print(*args, sep=sep, end=end, file=file, flush=flush)
    _print(*args, sep=sep, end=end, flush=flush)
    texto = sep.join(str(a) for a in args)
    if _P.fechado:
        return
    if not texto.strip():
        _P.espera(0.4); return
    _P.fala("npc", texto)
    _P.espera(0.9 + min(2.2, len(texto) * 0.03))


def _novo_input(prompt=""):
    if _P.fechado:
        return _input(prompt)
    _print(prompt, end="", flush=True)
    if str(prompt).strip():
        _P.fala("npc", str(prompt).strip(), pergunta=True)
    resposta = _P.pergunta()
    _print(resposta)
    _P.fala("heroi", resposta if resposta.strip() else "...")
    _P.espera(0.5)
    return resposta


builtins.print = _novo_print
builtins.input = _novo_input
npc, heroi, cenario, nome_heroi, entra, sai = _P.npc, _P.heroi, _P.cenario, _P.nome_heroi, _P.entra, _P.sai
narrar, placar, tremer, festa, espera = _P.narrar, _P.placar, _P.tremer, _P.festa, _P.espera
poder, arma, item, usar, tem, status = _P.poder, _P.arma, _P.item, _P.usar, _P.tem, _P.status
dano, cura, efeito, ajuda, vida = _P.dano, _P.cura, _P.efeito, _P.ajuda, _P.vida
diz, escolha, emocao, ataque, pular = _P.diz, _P.escolha, _P.emocao, _P.ataque, _P.pular
titulo, creditos, tela_cheia, musica = _P.titulo, _P.creditos, _P.tela_cheia, _P.musica
som = _P.som_liga


def vida_heroi(valor, maximo=None):
    _P.vida("heroi", valor, maximo)


def vida_npc(valor, maximo=None):
    _P.vida("npc", valor, maximo)


def velocidade(v):
    _P.vel = max(0.2, float(v)) * _P.turbo


def _quando_acabar():
    """Quando o SEU programa termina, a cena continua aberta (e explica o erro, se tiver)."""
    f = sys._getframe(0)
    while f is not None and f.f_globals.get("__name__") != "__main__":
        f = f.f_back
    mon = getattr(sys, "monitoring", None)
    if f is None or mon is None:
        return
    codigo = f.f_code
    _P.codigo_main = codigo
    tool = next((i for i in (4, 3) if mon.get_tool(i) is None), None)
    if tool is None:
        return
    mon.use_tool_id(tool, "palco")

    def acabou(code, offset, valor):
        if code is codigo:
            _P.fim()

    def deu_erro(code, offset, exc):
        if code is codigo:
            _P.erro(exc)

    mon.register_callback(tool, mon.events.PY_RETURN, acabou)
    mon.register_callback(tool, mon.events.PY_UNWIND, deu_erro)
    mon.set_local_events(tool, codigo, mon.events.PY_RETURN)
    mon.set_events(tool, mon.events.PY_UNWIND)


_quando_acabar()
atexit.register(_P.fim)
